pub type Door[State] = { state: State; }
pub type Open = {};
pub type Closed = {};

impl Door[Closed] {
  fn new() -> Door[Closed] { return Door{ state: Closed{} }; }
  fn open(self: Door[Closed]) -> Door[Open] { return Door{ state: Open{} }; }
}

impl Door[Open] {
  fn close(self: Door[Open]) -> Door[Closed] { return Door{ state: Closed{} }; }
}

fn main() -> Int {
  let d = Door::new();
  let d = d.open();
  let d = d.close();
  return 1;
}
